parameters.query:
select
  public.get_anthropic_key() as anthropic_key,
  (select agent_id from public.agent_routing where active = true and model_id = 'claude-haiku-4-5' limit 1) as agent_id,
  (select value from public.config where key = 'managed_agent_environment_id') as environment_id,
  (select vault_id from public.user_data_and_config where clickup_user_id = '2521617' and status = 'active' and vault_id is not null limit 1) as vault_id;

parameters.jsCode:
const inp = $input.first().json || {};
const key = (inp.anthropic_key || '').toString().trim();
const agent = (inp.agent_id || '').toString().trim();
const env = (inp.environment_id || '').toString().trim();
const vault = (inp.vault_id || '').toString().trim();
const t0 = Date.now();
const elapsed = function () { return Math.round((Date.now() - t0) / 1000); };
if (!key || !agent || !env || !vault) {
  return [{ json: { verdict: 'prereq_missing', elapsed_s: elapsed(), details: 'Brak wymaganych danych sondy (nie mozna wykonac testu): ' + JSON.stringify({ hasKey: !!key, agent: agent || null, env: env || null, hasVault: !!vault }) } }];
}
const API = 'https://api.anthropic.com';
const H = { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'managed-agents-2026-04-01,files-api-2025-04-14', 'content-type': 'application/json' };
const self = this;
const sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };
// up to 3 attempts, ~3000ms backoff, mirrors prod Create/Send maxTries:3. Returns {ok:true,body} or {ok:false,status,msg}.
const postWithRetry = async function (url, body) {
  let last = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await self.helpers.httpRequest({ method: 'POST', url: url, headers: H, body: body, json: true, timeout: 30000 });
      return { ok: true, body: res };
    } catch (e) {
      const status = (e && (e.statusCode || (e.response && e.response.status))) || null;
      last = { ok: false, status: status, msg: (e && e.message) ? String(e.message) : String(e) };
      if (attempt < 3) await sleep(3000);
    }
  }
  return last;
};
// 1) create the probe session with the ClickUp vault attached (retry transient Anthropic 5xx)
const created = await postWithRetry(API + '/v1/sessions', { agent: agent, environment_id: env, vault_ids: [vault] });
if (!created.ok) {
  return [{ json: { verdict: 'session_api_down', failedCall: 'create', status: created.status, elapsed_s: elapsed(), details: 'POST /v1/sessions nie powiodlo sie po 3 probach. status=' + (created.status || 'brak') + ' msg=' + (created.msg || '').slice(0, 200) } }];
}
const sid = created.body && created.body.id;
if (!sid) {
  return [{ json: { verdict: 'session_api_down', failedCall: 'create', status: 200, elapsed_s: elapsed(), details: 'Sonda: brak session id z /v1/sessions: ' + JSON.stringify(created.body).slice(0, 200) } }];
}
// 2) ask the agent to call ONLY the hierarchy tool (retry transient Anthropic 5xx)
const sent = await postWithRetry(API + '/v1/sessions/' + sid + '/events', { events: [{ type: 'user.message', content: [{ type: 'text', text: 'Test zdrowotny polaczenia z ClickUp. Wywolaj TERAZ narzedzie clickup_get_workspace_hierarchy i nic wiecej. NIE wywoluj zadnych innych narzedzi (ani get_task_details, ani deliver_output). Po wywolaniu odpowiedz jednym zdaniem.' }] }] });
if (!sent.ok) {
  try { await self.helpers.httpRequest({ method: 'DELETE', url: API + '/v1/sessions/' + sid, headers: H, timeout: 15000 }); } catch (e) {}
  return [{ json: { verdict: 'session_api_down', failedCall: 'send', status: sent.status, session_id: sid, elapsed_s: elapsed(), details: 'POST /v1/sessions/{id}/events nie powiodlo sie po 3 probach. status=' + (sent.status || 'brak') + ' msg=' + (sent.msg || '').slice(0, 200) } }];
}
// 3) poll for a connectivity verdict
let connected = false; const denied = []; let clickupCustom = false; let sessErr = null;
for (let i = 0; i < 12; i++) {
  await sleep(4000);
  let ev;
  try { ev = await self.helpers.httpRequest({ method: 'GET', url: API + '/v1/sessions/' + sid + '/events?limit=100', headers: H, json: true, timeout: 30000 }); } catch (e) { continue; }
  const data = (ev && Array.isArray(ev.data)) ? ev.data : [];
  for (const e of data) {
    const nm = (e && typeof e.name === 'string') ? e.name : '';
    if (e.type === 'agent.mcp_tool_use' && nm.indexOf('clickup_') === 0) connected = true;
    if (e.type === 'agent.custom_tool_use' && nm.indexOf('clickup_') === 0) clickupCustom = true;
    if (e.type === 'agent.tool_result') { const t = Array.isArray(e.content) ? e.content.map(function (c) { return (c && c.text) || ''; }).join(' ') : ''; const m = t.match(/Permission to use (clickup_[A-Za-z0-9_]+) has been denied/); if (m) denied.push(m[1]); }
    if (e.type === 'session.error' || (typeof e.type === 'string' && e.type.indexOf('error') >= 0 && e.error)) { const errObj = e.error || e; if (JSON.stringify(errObj || {}).toLowerCase().indexOf('clickup') >= 0) sessErr = errObj; }
  }
  if (connected || denied.length || clickupCustom || sessErr) break;
}
const el = elapsed();
// best-effort cleanup (idle probe session otherwise lingers; harmless if DELETE is unsupported)
try { await self.helpers.httpRequest({ method: 'DELETE', url: API + '/v1/sessions/' + sid, headers: H, timeout: 15000 }); } catch (e) {}
if (connected) { return [{ json: { verdict: 'healthy', session_id: sid, elapsed_s: el } }]; }
if (denied.length || clickupCustom || sessErr) {
  return [{ json: { verdict: 'clickup_down', session_id: sid, elapsed_s: el, details: 'Sonda ClickUp MCP: narzedzie NIE polaczylo sie (' + el + 's). denied=' + JSON.stringify(denied) + ' routedAsCustom=' + clickupCustom + ' sessionError=' + (sessErr ? JSON.stringify(sessErr).slice(0, 200) : 'brak') + ' session=' + sid } }];
}
// inconclusive: the agent did not attempt the tool within budget (steering miss, not an outage) -> do not alarm
return [{ json: { verdict: 'healthy', inconclusive: true, session_id: sid, elapsed_s: el, note: 'Agent nie wywolal clickup_get_workspace_hierarchy w oknie sondy - wynik niejednoznaczny, brak alarmu.' } }];
